                                 previous,
                                 isMinim),
                            isMinim);

                if (checker != null) {
                    if (checker.converged(iter, previous, current)) {
                        return best;
                    }
                }

                // Update a, b, v, w and x.
                if (fu <= fx) {
                    if (u < x) {
                        b = x;
                    } else {
                        a = x;
                    }
                    v = w;
                    fv = fw;
                    w = x;
